import{_ as a,o,c as t,a3 as r}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Work and labour rights","description":"Contracts, hours, leave, wages, the end-of-service gratuity, changing employers, leaving Qatar and how to raise a complaint, for private-sector workers.","frontmatter":{"title":"Work and labour rights","description":"Contracts, hours, leave, wages, the end-of-service gratuity, changing employers, leaving Qatar and how to raise a complaint, for private-sector workers.","lastChecked":"2026-11","sourceCount":3},"headers":[],"relativePath":"guide/work-and-labour-rights.md","filePath":"guide/work-and-labour-rights.md"}'),f={name:"guide/work-and-labour-rights.md"};function n(s,e,i,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="work-and-labour-rights" tabindex="-1">Work and labour rights <a class="header-anchor" href="#work-and-labour-rights" aria-label="Permalink to &quot;Work and labour rights&quot;">​</a></h1><p>This page covers the basic rights of people working for private employers in Qatar. It does not apply to public-sector employees, the armed forces or people working at sea, and domestic workers have some separate rules.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>Almost everything here comes from the National Human Rights Committee&#39;s Worker&#39;s Pocket Booklet, sixth edition, December 2021. It is a plain-language summary, not the law itself, and it tells readers to watch for later changes and to check the minimum wage with the Ministry of Labour. Treat the figures below as a starting point and confirm anything important with the Ministry.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="your-contract" tabindex="-1">Your contract <a class="header-anchor" href="#your-contract" aria-label="Permalink to &quot;Your contract&quot;">​</a></h2><ul><li>You need a written contract signed by you and your employer. Working without one is against the law.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>The contract should state the employer&#39;s name and place of work, your details, the type of work, the start date, the length of the contract if it is fixed, and the agreed wage with how and when it is paid.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>Keep a copy. If you were not given one, you can complain to the Labour Relations Department at the Ministry of Labour.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>A fixed-term contract cannot be longer than five years, and it can be renewed by agreement.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>Probation cannot be longer than six months, and the same employer can only put you on probation once.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li><li>Recruitment offices in Qatar are not allowed to charge you recruitment fees or expenses.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li></ul><p>Your employer may not hold your passport unless you asked for that in writing, and it must be returned when you ask. If it is refused, you can complain to the police or the public prosecution.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></p><h2 id="hours-and-rest" tabindex="-1">Hours and rest <a class="header-anchor" href="#hours-and-rest" aria-label="Permalink to &quot;Hours and rest&quot;">​</a></h2><ul><li>Normal hours are eight a day, and six a day during Ramadan. Rest breaks do not count as working time.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1]</a></sup></li><li>With overtime, the total should not go above ten hours a day, apart from urgent cases such as preventing serious loss or dealing with an accident.<sup class="footnote-ref"><a href="#fn1" id="fnref1:10">[1]</a></sup></li><li>Overtime is paid at your basic wage plus at least 25 percent.<sup class="footnote-ref"><a href="#fn1" id="fnref1:11">[1]</a></sup></li><li>Work between 9 pm and 3 am is paid at your basic wage plus 50 percent, except for shift workers.<sup class="footnote-ref"><a href="#fn1" id="fnref1:12">[1]</a></sup></li><li>Friday is the normal weekly rest day, except for shift workers. If you work on it, you get your basic pay for the day plus another rest day, or your basic pay plus 150 percent.<sup class="footnote-ref"><a href="#fn1" id="fnref1:13">[1]</a></sup></li><li>You cannot be made to work more than two Fridays in a row, even if you agree to it.<sup class="footnote-ref"><a href="#fn1" id="fnref1:14">[1]</a></sup></li></ul><h2 id="leave" tabindex="-1">Leave <a class="header-anchor" href="#leave" aria-label="Permalink to &quot;Leave&quot;">​</a></h2><ul><li>Annual leave is three weeks a year if you have less than five years of service, and four weeks with five years or more. Part-years are worked out in proportion.<sup class="footnote-ref"><a href="#fn1" id="fnref1:15">[1]</a></sup></li><li>Your employer sets the dates based on the needs of the work and must pay you for the leave before you take it.<sup class="footnote-ref"><a href="#fn1" id="fnref1:16">[1]</a></sup></li><li>You cannot give up your right to annual leave. If your contract ends first, you must be paid for the days you are owed.<sup class="footnote-ref"><a href="#fn1" id="fnref1:17">[1]</a></sup></li><li>Sick leave starts only after three months in the job and needs a certificate from a doctor your employer approves.<sup class="footnote-ref"><a href="#fn1" id="fnref1:18">[1]</a></sup></li><li>The first two weeks of sick leave are on full pay, the next four weeks on half pay, and anything after that is unpaid.<sup class="footnote-ref"><a href="#fn1" id="fnref1:19">[1]</a></sup></li><li>Public holidays have their own rules, covered in <a href="./holidays-and-ramadan">Public holidays and Ramadan working hours</a>.<sup class="footnote-ref"><a href="#fn1" id="fnref1:20">[1]</a></sup></li></ul><h2 id="wages" tabindex="-1">Wages <a class="header-anchor" href="#wages" aria-label="Permalink to &quot;Wages&quot;">​</a></h2><ul><li>The Wage Protection System requires employers to pay wages into your account within seven days of the due date. A Ministry of Labour department monitors this.<sup class="footnote-ref"><a href="#fn1" id="fnref1:21">[1]</a></sup></li><li>The booklet gives the minimum wage as QAR 1,000 a month. If your employer does not provide adequate housing or food, it adds at least QAR 500 for housing and QAR 300 for food. Check the current amounts with the Ministry.<sup class="footnote-ref"><a href="#fn1" id="fnref1:22">[1]</a></sup></li></ul><h2 id="end-of-service-gratuity" tabindex="-1">End-of-service gratuity <a class="header-anchor" href="#end-of-service-gratuity" aria-label="Permalink to &quot;End-of-service gratuity&quot;">​</a></h2><p>You qualify after a full year of work or more, and it covers all your years of service. If you disagree with your employer about how many years count, you can complain to the Labour Relations Department.<sup class="footnote-ref"><a href="#fn1" id="fnref1:23">[1]</a></sup></p><h3 id="how-much-it-is" tabindex="-1">How much it is <a class="header-anchor" href="#how-much-it-is" aria-label="Permalink to &quot;How much it is&quot;">​</a></h3><p>This part comes from Article 54 of the Labour Law, not the booklet:<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><ul><li>You and your employer can agree the amount, but it cannot be less than three weeks&#39; wage for each year of service.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li>Part of a year counts in proportion.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li>It is worked out on your last basic wage.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li>Your basic wage is the pay for your work, including your annual increase. Allowances and bonuses come on top of it, so they do not count here.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup><sup class="footnote-ref"><a href="#fn1" id="fnref1:24">[1]</a></sup></li><li>Your employer can deduct money you owe it from the gratuity.<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2]</a></sup></li><li>If your service ended for a reason other than those in Article 61 and you return to service within two months, it counts as unbroken.<sup class="footnote-ref"><a href="#fn2" id="fnref2:6">[2]</a></sup></li></ul><p>For domestic workers, the booklet says at least three weeks&#39; wage for each year of service.<sup class="footnote-ref"><a href="#fn1" id="fnref1:25">[1]</a></sup></p><p>The only copy of the law we could read is an English translation on the government portal, in a file from January 2006. The booklet shows that this law was amended in 2020, and we could not open the current text to check that Article 54 is unchanged. Confirm the amount with the Ministry of Labour before you rely on it.<sup class="footnote-ref"><a href="#fn2" id="fnref2:7">[2]</a></sup><sup class="footnote-ref"><a href="#fn1" id="fnref1:26">[1]</a></sup></p><h3 id="when-you-keep-it-and-when-you-can-lose-it" tabindex="-1">When you keep it, and when you can lose it <a class="header-anchor" href="#when-you-keep-it-and-when-you-can-lose-it" aria-label="Permalink to &quot;When you keep it, and when you can lose it&quot;">​</a></h3><p>You can end your contract without notice and keep your gratuity in these cases:<sup class="footnote-ref"><a href="#fn1" id="fnref1:27">[1]</a></sup></p><ul><li>Your employer breaks the contract or the labour law.<sup class="footnote-ref"><a href="#fn1" id="fnref1:28">[1]</a></sup></li><li>Your employer assaults you or a member of your family, or commits an immoral act against you or them.<sup class="footnote-ref"><a href="#fn1" id="fnref1:29">[1]</a></sup></li><li>Your employer misled you about the terms of the contract.<sup class="footnote-ref"><a href="#fn1" id="fnref1:30">[1]</a></sup></li><li>There is a serious danger to your safety or health that your employer knew about and did not remove.<sup class="footnote-ref"><a href="#fn1" id="fnref1:31">[1]</a></sup></li><li>A labour dispute settlement committee has issued a final decision in your favour.<sup class="footnote-ref"><a href="#fn1" id="fnref1:32">[1]</a></sup></li></ul><p>Your employer can end your contract without notice and without the gratuity in these cases:<sup class="footnote-ref"><a href="#fn1" id="fnref1:33">[1]</a></sup></p><ul><li>You used a false identity or nationality, or gave false papers, documents or certificates.<sup class="footnote-ref"><a href="#fn1" id="fnref1:34">[1]</a></sup></li><li>You made a mistake that caused the employer a serious financial loss.<sup class="footnote-ref"><a href="#fn1" id="fnref1:35">[1]</a></sup></li><li>You broke the safety instructions more than once despite a written warning. The instructions must be written and displayed where you can see them.<sup class="footnote-ref"><a href="#fn1" id="fnref1:36">[1]</a></sup></li><li>You broke your contract or the labour law more than once despite a written warning.<sup class="footnote-ref"><a href="#fn1" id="fnref1:37">[1]</a></sup></li><li>You were under the influence of drugs or alcohol during work hours.<sup class="footnote-ref"><a href="#fn1" id="fnref1:38">[1]</a></sup></li><li>You assaulted your employer, a manager or a colleague during work, or kept assaulting colleagues after a written warning.<sup class="footnote-ref"><a href="#fn1" id="fnref1:39">[1]</a></sup></li><li>You were absent without a legitimate reason for more than seven days in a row, or for fifteen days on and off in a year.<sup class="footnote-ref"><a href="#fn1" id="fnref1:40">[1]</a></sup></li><li>You were convicted, in a final judgment, of a crime of honour or honesty.<sup class="footnote-ref"><a href="#fn1" id="fnref1:41">[1]</a></sup></li></ul><p>The 2006 copy of the law also lists revealing the company&#39;s secrets, which the booklet does not mention.<sup class="footnote-ref"><a href="#fn2" id="fnref2:8">[2]</a></sup></p><p>If you think a dismissal was arbitrary or against the law, you can appeal it before the Labour Disputes Settlement Committee. If it agrees, it either cancels the dismissal, returns you to work and awards your wages for the time you lost, or orders fair compensation.<sup class="footnote-ref"><a href="#fn1" id="fnref1:42">[1]</a></sup></p><p>Do not ignore a dismissal under Article 61. If you do not challenge it, or you challenge it and lose, you cannot return to work until four years after you left Qatar.<sup class="footnote-ref"><a href="#fn1" id="fnref1:43">[1]</a></sup></p><h2 id="changing-employers" tabindex="-1">Changing employers <a class="header-anchor" href="#changing-employers" aria-label="Permalink to &quot;Changing employers&quot;">​</a></h2><p>You can apply to change employer before your contract ends, without a certificate of objection from your current employer.<sup class="footnote-ref"><a href="#fn1" id="fnref1:44">[1]</a></sup></p><ol><li>Tell your current employer through the Ministry of Labour&#39;s electronic notification system. This includes your documented contract and a letter from the new employer. Your residence permit must be valid, or within 90 days of expiry, unless it expired for reasons beyond your control.<sup class="footnote-ref"><a href="#fn1" id="fnref1:45">[1]</a></sup></li><li>Give notice: one month if you have worked there for two years or less, two months if longer.<sup class="footnote-ref"><a href="#fn1" id="fnref1:46">[1]</a></sup></li><li>When the Ministry approves by text message, the new employer completes the new contract on the Ministry&#39;s digital system.<sup class="footnote-ref"><a href="#fn1" id="fnref1:47">[1]</a></sup></li><li>The case then moves to the Ministry of Interior, and the new employer applies for your new Qatar ID through Metrash.<sup class="footnote-ref"><a href="#fn1" id="fnref1:48">[1]</a></sup></li></ol><p>The process is free for you, so do not pay anyone for it. If your employer is not meeting its legal duties, including paying your wages, you can change without notice, and you must file a complaint with the Labour Relations Department.<sup class="footnote-ref"><a href="#fn1" id="fnref1:49">[1]</a></sup></p><p>If you have worked at least one year, your current employer owes you your gratuity when you change jobs, along with your accumulated annual leave and any other benefits in your contract.<sup class="footnote-ref"><a href="#fn1" id="fnref1:50">[1]</a></sup></p><p>Check your contract for a non-competition clause. It can only apply if your work gives you access to clients or business secrets, and it cannot last more than one year.<sup class="footnote-ref"><a href="#fn1" id="fnref1:51">[1]</a></sup></p><h2 id="leaving-qatar" tabindex="-1">Leaving Qatar <a class="header-anchor" href="#leaving-qatar" aria-label="Permalink to &quot;Leaving Qatar&quot;">​</a></h2><ul><li>You can leave, for a short trip or for good, without your employer&#39;s permission. An employer can ask for prior approval only for named staff, up to 5 percent of its workforce, because of the nature of their work.<sup class="footnote-ref"><a href="#fn1" id="fnref1:52">[1]</a></sup></li><li>If you are stopped from leaving, you can go to the Expatriates Exit Grievances Committee, which must decide within three working days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:53">[1]</a></sup></li><li>If your residence permit ends or is cancelled, you have 90 days to leave.<sup class="footnote-ref"><a href="#fn1" id="fnref1:54">[1]</a></sup></li><li>If you leave without working your notice, you may not get a work permit for one year from the date you left.<sup class="footnote-ref"><a href="#fn1" id="fnref1:55">[1]</a></sup></li><li>At the end of a contract, your employer must arrange and pay for your ticket home within two weeks. If you join another job first, that duty passes to the new employer.<sup class="footnote-ref"><a href="#fn1" id="fnref1:56">[1]</a></sup></li></ul><h2 id="how-to-raise-a-complaint" tabindex="-1">How to raise a complaint <a class="header-anchor" href="#how-to-raise-a-complaint" aria-label="Permalink to &quot;How to raise a complaint&quot;">​</a></h2><ol><li>Start inside the company, with your supervisors or the joint committee if there is one.<sup class="footnote-ref"><a href="#fn1" id="fnref1:57">[1]</a></sup></li><li>If that fails, go to the Labour Relations Department at the Ministry of Labour, which tries to settle the dispute within seven days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:58">[1]</a></sup></li><li>If it is not settled, the department refers it to the Labour Disputes Settlement Committee within three working days. You cannot go straight to the committee.<sup class="footnote-ref"><a href="#fn1" id="fnref1:59">[1]</a></sup></li><li>The committee decides within three weeks of its first session. Either side can appeal to the Court of Appeal within fifteen days.<sup class="footnote-ref"><a href="#fn1" id="fnref1:60">[1]</a></sup></li></ol><p>If the authorities do not respond, the National Human Rights Committee offers free legal advice.<sup class="footnote-ref"><a href="#fn1" id="fnref1:61">[1]</a></sup> Its hotline is 8002222, and you can complain by email at <a href="mailto:c@nhrc.org.qa" target="_blank" rel="noreferrer">c@nhrc.org.qa</a>, by phone, by fax, in person or online.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><p>For a complaint, write clearly what happened, give your contact details, and attach a copy of your passport or visa along with any supporting documents. Qataris attach a copy of their ID card instead.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></p><p>See also: <a href="./residence-permit-and-qid">Residence permit and QID</a>, <a href="./metrash">Metrash</a>, <a href="./holidays-and-ramadan">Public holidays and Ramadan working hours</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>National Human Rights Committee, <a href="https://www.nhrc-qa.org/storage/publications/file_6666d6f57f82d_1718015733.pdf" target="_blank" rel="noreferrer">Worker&#39;s Pocket Booklet, sixth edition, December 2021</a>. Last checked: 2026-11. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:11" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:12" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:13" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:14" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:15" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:16" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:17" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:18" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:19" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:20" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:21" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:22" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:23" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:24" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:25" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:26" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:27" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:28" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:29" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:30" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:31" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:32" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:33" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:34" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:35" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:36" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:37" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:38" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:39" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:40" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:41" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:42" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:43" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:44" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:45" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:46" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:47" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:48" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:49" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:50" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:51" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:52" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:53" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:54" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:55" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:56" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:57" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:58" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:59" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:60" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:61" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Government of Qatar portal, <a href="https://portal.www.gov.qa/wps/wcm/connect/5f30f680423f8a149631df3cb857e4ca/Qatar+Labor+Law.pdf?MOD=AJPERES" target="_blank" rel="noreferrer">Labour Law of the State of Qatar, issued 19 May 2004, English translation, file from January 2006</a>. Last checked: 2026-11. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>National Human Rights Committee, <a href="https://www.nhrc-qa.org/" target="_blank" rel="noreferrer">Home page, contact and complaints section</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',43)])])}const d=a(f,[["render",n]]);export{p as __pageData,d as default};
